export const categoriesList = Object.values(categoriesData);

export function getAllCategories() {
  return categoriesList;
}

export function getCategoryBySlug(slug) {
  if (!slug) return categoriesData['others'];
  const normalized = String(slug).toLowerCase().trim();
  
  if (categoriesData[normalized]) {
    return categoriesData[normalized];
  }
  
  // Search by shortTitle or name
  const found = categoriesList.find(
    c => c.slug.toLowerCase() === normalized ||
         c.shortTitle.toLowerCase() === normalized ||
         c.name.toLowerCase() === normalized ||
         normalized.includes(c.slug.toLowerCase())
  );
  
  if (found) return found;
  
  // Default fallback if category does not match: return 'others'
  return categoriesData['others'];
}

export function getAllServicesFlat() {
  const flat = [];
  for (const cat of categoriesList) {
    for (const s of cat.services) {
      flat.push({
        ...s,
        categorySlug: cat.slug,
        categoryName: cat.name,
        categoryShort: cat.shortTitle,
        categoryBadge: cat.badge
      });
    }
  }
  return flat;
}
